            elif tok == '*':
                stack.append(a * b)
            else:
                # truncate toward zero
                q = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    q = -q
                stack.append(q)
        else:
            stack.append(int(tok))
    return stack[0]
