def solve(matrix):
    """Return the determinant of a square integer matrix, as an int.

    Uses the Bareiss algorithm so all intermediate values stay integers.
    An empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    a = [[int(x) for x in row] for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            pivot_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    pivot_row = i
                    break
            if pivot_row is None:
                return 0  # entire column is zero below => determinant 0
            a[k], a[pivot_row] = a[pivot_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss step: division is exact for integer matrices.
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

