def solve(n, b):
    """Convert integer n to its representation in base b (2..36).

    Digits are 0-9 then lowercase a-z; negative n gets a leading '-'.
    """
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    negative = n < 0
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, b)
        out.append(digits[r])
    if negative:
        out.append('-')
    return ''.join(reversed(out))

