def solve(grid):
    """Return the fewest steps from top-left to bottom-right in a 0/1 grid,
    moving up/down/left/right through open cells (0); -1 if no path.
    """
    if not grid or not grid[0]:
        return -1
    n, m = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[n - 1][m - 1] == 1:
        return -1
    from collections import deque
    dist = {(0, 0): 0}
    q = deque([(0, 0)])
    while q:
        i, j = q.popleft()
        d = dist[(i, j)]
        if (i, j) == (n - 1, m - 1):
            return d
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 0 and (ni, nj) not in dist:
                dist[(ni, nj)] = d + 1
                q.append((ni, nj))
    return -1

